<?php
declare(strict_types=1);ob_start();require __DIR__.'/app/bootstrap.php';require_once __DIR__.'/app/super_app_v700.php';$u=v700_require_user();$uid=(int)$u['id'];$book=v700_rows("SELECT b.*,t.departure_at,r.origin,r.destination FROM transport_bookings_v700 b JOIN transport_trips_v700 t ON t.id=b.trip_id JOIN transport_routes_v700 r ON r.id=t.route_id WHERE b.tenant_id=? AND b.user_id=? ORDER BY b.id DESC",[v700_tid(),$uid]);$rides=v700_rows("SELECT * FROM ride_requests_v700 WHERE tenant_id=? AND user_id=? ORDER BY id DESC",[v700_tid(),$uid]);$del=v700_rows("SELECT * FROM delivery_orders_v700 WHERE tenant_id=? AND user_id=? ORDER BY id DESC",[v700_tid(),$uid]);v700_public_header('My Travel & Delivery','Trips, rides and delivery requests.','transport');?>
<main><section class="v700-account-hero"><div class="v700-shell"><span class="v700-kicker">MY MOBILITY</span><h1>Travel & delivery dashboard</h1><p>Track bookings, rides and delivery status from one place.</p></div></section><section class="v700-section soft"><div class="v700-shell"><div class="v700-account-grid"><a href="#trips"><b><?=count($book)?></b><span>Trip Bookings</span></a><a href="#rides"><b><?=count($rides)?></b><span>Ride Requests</span></a><a href="#deliveries"><b><?=count($del)?></b><span>Deliveries</span></a><a href="/transport.php"><b>+</b><span>Book Travel</span></a></div><section class="v700-panel" id="trips"><div class="v700-panel-head"><h2>Trips</h2></div><div class="v700-list"><?php foreach($book as $b):?><div class="v700-row"><i>🚌</i><span><b><?=e($b['origin'])?> → <?=e($b['destination'])?></b><small><?=e($b['booking_no'])?> · <?=e(date('d M h:i A',strtotime($b['departure_at'])))?></small></span><?=v700_status_badge($b['status'])?></div><?php endforeach;?></div></section><section class="v700-panel" id="rides"><div class="v700-panel-head"><h2>Rides</h2></div><div class="v700-list"><?php foreach($rides as $r):?><div class="v700-row"><i>🚕</i><span><b><?=e($r['pickup_address'])?> → <?=e($r['destination_address'])?></b><small><?=e($r['request_no'])?></small></span><?=v700_status_badge($r['status'])?></div><?php endforeach;?></div></section><section class="v700-panel" id="deliveries"><div class="v700-panel-head"><h2>Deliveries</h2></div><div class="v700-list"><?php foreach($del as $d):?><div class="v700-row"><i>📦</i><span><b><?=e($d['pickup_address'])?> → <?=e($d['dropoff_address'])?></b><small><?=e($d['delivery_no'])?> · <?=e(ucfirst($d['delivery_type']))?></small></span><?=v700_status_badge($d['status'])?></div><?php endforeach;?></div></section></div></section></main><?php v700_public_footer(); ?>
